function minChanges(nums, k) {
  const MAX = 1024;
  let dp = new Array(MAX).fill(Infinity);
  dp[0] = 0;
  for (let group = 0; group < k; group++) {
    const count = new Map();
    let size = 0;
    for (let i = group; i < nums.length; i += k) {
      count.set(nums[i], (count.get(nums[i]) || 0) + 1);
      size++;
    }
    const best = Math.min(...dp);
    const next = new Array(MAX).fill(best + size);
    for (let x = 0; x < MAX; x++) {
      for (const [value, freq] of count) {
        const cost = dp[x] + size - freq;
        if (cost < next[x ^ value]) {
          next[x ^ value] = cost;
        }
      }
    }
    dp = next;
  }
  return dp[0];
}

