function minChanges(nums, k) {
  // Every window XOR is 0 exactly when the array repeats with period k and its first k values XOR to 0.
  // Any optimum can use values below the next power of two above max(nums), so try all such patterns.
  let span = 1;
  while (span <= Math.max(...nums)) span *= 2;
  let best = Infinity;
  const pattern = new Array(k).fill(0);
  const total = span ** (k - 1);
  for (let code = 0; code < total; code++) {
    let rest = code, xor = 0;
    for (let j = 0; j < k - 1; j++) { pattern[j] = rest % span; rest = Math.floor(rest / span); xor ^= pattern[j]; }
    pattern[k - 1] = xor;
    let changes = 0;
    for (let i = 0; i < nums.length; i++) if (nums[i] !== pattern[i % k]) changes++;
    if (changes < best) best = changes;
  }
  return best;
}

