function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 9);
    const k = int(1, Math.min(n, 4));
    const top = rand() < 0.5 ? 3 : 7;
    // Sometimes start from a valid periodic array and disturb it, so small answers appear too.
    if (rand() < 0.4) {
      const base = Array.from({ length: k }, () => int(0, top));
      base[k - 1] = base.slice(0, k - 1).reduce((a, b) => a ^ b, 0);
      const nums = Array.from({ length: n }, (_, i) => rand() < 0.25 ? int(0, top) : base[i % k]);
      return [nums, k];
    }
    return [Array.from({ length: n }, () => int(0, top)), k];
  }
  const n = int(1500, 2000);
  const shape = rand();
  const k = shape < 0.4 ? int(1, 12) : shape < 0.8 ? int(13, 300) : int(301, n);
  const base = Array.from({ length: k }, () => int(0, 1023));
  base[k - 1] = base.slice(0, k - 1).reduce((a, b) => a ^ b, 0);
  const noise = rand() * 0.7;
  const nums = Array.from({ length: n }, (_, i) => rand() < noise ? int(0, 1023) : base[i % k]);
  return [nums, k];
}
